import 'dart:async';

import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

// Generated by `dart run flutterfire configure` (see README).
import 'firebase_options.dart';
import 'services/alert_listener_service.dart';
import 'services/alert_service.dart';
import 'services/limit_resolver.dart';
import 'services/location_service.dart';
import 'services/overspeed_detector.dart';
import 'services/pairing_service.dart';
import 'services/speed_limit_service.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  runApp(const SpeedGuardianApp());
}

class SpeedGuardianApp extends StatelessWidget {
  const SpeedGuardianApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Speed Guardian',
      theme: ThemeData(colorSchemeSeed: Colors.teal, useMaterial3: true),
      home: const HomePage(),
    );
  }
}

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  final _pairing = PairingService();
  final _location = LocationService();
  final _limits = SpeedLimitService();
  final _alerts = AlertService();
  final _alertListener = AlertListenerService();
  final _detector = OverspeedDetector();
  final _codeController = TextEditingController();

  StreamSubscription<SpeedReading>? _sub;
  bool _ready = false;
  bool _driving = false;
  double _speed = 0;
  double? _limit;
  LimitSource _limitSource = LimitSource.unknown;

  /// Speed limit chosen by hand; null means "automatic" (map data).
  double? _manualLimit;
  static const _manualOptions = [30, 40, 50, 60, 80, 100, 120];

  String? _message;

  @override
  void initState() {
    super.initState();
    _pairing.init().then((_) async {
      // Show a local notification when the partner is speeding.
      await _alertListener.init();
      _alertListener.start(_pairing.uid);
      if (mounted) setState(() => _ready = true);
    });
  }

  @override
  void dispose() {
    _sub?.cancel();
    _alertListener.stop();
    _codeController.dispose();
    super.dispose();
  }

  Future<void> _startDriving(String? partnerUid) async {
    if (partnerUid == null) {
      setState(() => _message = 'اربط حسابك بالشريك أولا');
      return;
    }
    if (!await _location.ensurePermission()) {
      setState(() => _message = 'لازم تفعّل الموقع (Location)');
      return;
    }

    _detector.reset();
    _sub = _location.speedStream().listen((r) async {
      // A manual choice wins, so skip the map request when one is set.
      final manual = _manualLimit;
      final mapLimit =
          manual == null ? await _limits.limitAt(r.latitude, r.longitude) : null;
      final resolved = resolveLimit(manualKmh: _manualLimit, mapKmh: mapLimit);
      final limit = resolved.kmh;
      final event = _detector.update(
        speedKmh: r.speedKmh,
        limitKmh: limit,
        now: r.timestamp,
      );

      if (event != OverspeedEvent.none) {
        // Warn the driver first: this is what actually reduces speed.
        HapticFeedback.heavyImpact();
        SystemSound.play(SystemSoundType.alert);
      }
      if (event == OverspeedEvent.alertPartner && limit != null) {
        await _alerts.sendOverspeedAlert(
          fromUid: _pairing.uid,
          toUid: partnerUid,
          speedKmh: r.speedKmh,
          limitKmh: limit,
        );
      }

      if (!mounted) return;
      setState(() {
        _speed = r.speedKmh;
        _limit = limit;
        _limitSource = resolved.source;
      });
    });
    setState(() {
      _driving = true;
      _message = null;
    });
  }

  Future<void> _stopDriving() async {
    await _sub?.cancel();
    _sub = null;
    _detector.reset();
    setState(() {
      _driving = false;
      _speed = 0;
    });
  }

  /// Pick the limit by hand, or pass null to go back to automatic (map) mode.
  void _setManualLimit(double? value) {
    setState(() {
      _manualLimit = value;
      if (value != null) {
        _limit = value;
        _limitSource = LimitSource.manual;
      } else {
        _limit = null;
        _limitSource = LimitSource.unknown;
      }
    });
  }

  String _limitText() {
    final limit = _limit;
    if (limit == null) return 'السرعة القصوى: غير معروفة';
    final source =
        _limitSource == LimitSource.manual ? 'يدوي' : 'من الخريطة';
    return 'السرعة القصوى: ${limit.round()} km/h ($source)';
  }

  /// Sends a fake alert to the partner so the whole chain can be tested without driving.
  Future<void> _sendTestAlert(String partnerUid) async {
    try {
      await _alerts.sendOverspeedAlert(
        fromUid: _pairing.uid,
        toUid: partnerUid,
        speedKmh: 90,
        limitKmh: 50,
      );
      setState(() => _message = 'تم إرسال تنبيه تجريبي للشريك ✅');
    } catch (e) {
      setState(() => _message = 'فشل الإرسال: $e');
    }
  }

  Future<void> _pair() async {
    final ok = await _pairing.pairWith(_codeController.text);
    setState(() => _message = ok ? 'تم الربط ✅' : 'الكود غير صحيح');
  }

  @override
  Widget build(BuildContext context) {
    if (!_ready) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    return Scaffold(
      appBar: AppBar(title: const Text('Speed Guardian')),
      body: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        stream: _pairing.myDoc(),
        builder: (context, snap) {
          final data = snap.data?.data();
          final myCode = data?['pairCode'] as String? ?? '...';
          final partnerUid = data?['partnerUid'] as String?;

          return ListView(
            padding: const EdgeInsets.all(20),
            children: [
              Card(
                child: Padding(
                  padding: const EdgeInsets.all(16),
                  child: Column(
                    children: [
                      Text(
                        '${_speed.round()} km/h',
                        style: Theme.of(context).textTheme.displayMedium,
                      ),
                      Text(_limitText()),
                    ],
                  ),
                ),
              ),
              const SizedBox(height: 16),
              const Text(
                'السرعة القصوى للطريق',
                textAlign: TextAlign.center,
              ),
              const SizedBox(height: 8),
              Wrap(
                spacing: 8,
                runSpacing: 8,
                alignment: WrapAlignment.center,
                children: [
                  ChoiceChip(
                    label: const Text('تلقائي'),
                    selected: _manualLimit == null,
                    onSelected: (_) => _setManualLimit(null),
                  ),
                  for (final v in _manualOptions)
                    ChoiceChip(
                      label: Text('$v'),
                      selected: _manualLimit == v.toDouble(),
                      onSelected: (_) => _setManualLimit(v.toDouble()),
                    ),
                ],
              ),
              if (_manualLimit == null && _limit == null)
                const Padding(
                  padding: EdgeInsets.only(top: 8),
                  child: Text(
                    'إذا بقيت غير معروفة، اختر السرعة القصوى يدويا '
                    'باش يشتغل التنبيه.',
                    textAlign: TextAlign.center,
                  ),
                ),
              const SizedBox(height: 16),
              FilledButton.icon(
                onPressed:
                    _driving ? _stopDriving : () => _startDriving(partnerUid),
                icon: Icon(_driving ? Icons.stop : Icons.directions_car),
                label: Text(_driving ? 'وقف القيادة' : 'بدأ القيادة'),
              ),
              if (_message != null)
                Padding(
                  padding: const EdgeInsets.only(top: 12),
                  child: Text(_message!, textAlign: TextAlign.center),
                ),
              const Divider(height: 40),
              Text('كود الربط تاعك: $myCode',
                  style: Theme.of(context).textTheme.titleMedium),
              const SizedBox(height: 8),
              if (partnerUid == null) ...[
                TextField(
                  controller: _codeController,
                  textCapitalization: TextCapitalization.characters,
                  decoration: const InputDecoration(
                    labelText: 'دخل كود الشريك',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 8),
                OutlinedButton(onPressed: _pair, child: const Text('اربط')),
              ] else ...[
                const Text('مربوط بالشريك ✅'),
                OutlinedButton.icon(
                  onPressed: () => _sendTestAlert(partnerUid),
                  icon: const Icon(Icons.notifications_active),
                  label: const Text('جرّب تنبيه للشريك'),
                ),
                TextButton(
                  onPressed: () => _pairing.unpair(partnerUid),
                  child: const Text('فك الربط'),
                ),
              ],
            ],
          );
        },
      ),
    );
  }
}
